inline_styles:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

    :root {
      --green-dark: #0A4A2E;
      --green-mid: #1a6b45;
      --green-light: #e8f5ee;
      --accent: #f0a500;
      --text: #1a1a2e;
      --muted: #6b7280;
      --border: #e5e7eb;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--text); background: #fafaf8; line-height: 1.7; }

    nav {
      background: var(--green-dark);
      padding: 16px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    nav a.logo { color: white; text-decoration: none; font-weight: 800; font-size: 1.1rem; }
    nav a.cta-nav {
      background: var(--accent); color: #1a1a00; padding: 8px 18px;
      border-radius: 6px; text-decoration: none; font-weight: 700; font-size: 0.85rem;
    }

    .hero {
      background: linear-gradient(135deg, var(--green-dark) 0%, #1a6b45 100%);
      color: white; padding: 60px 24px 48px; text-align: center;
    }
    .hero .tag {
      display: inline-block; background: rgba(255,255,255,0.15);
      border: 1px solid rgba(255,255,255,0.3); padding: 4px 14px; border-radius: 20px;
      font-size: 0.8rem; font-weight: 600; letter-spacing: 0.05em; margin-bottom: 18px; text-transform: uppercase;
    }
    .hero h1 { font-size: clamp(1.6rem, 4vw, 2.4rem); font-weight: 800; line-height: 1.25; max-width: 700px; margin: 0 auto 16px; }
    .hero p { font-size: 1.05rem; opacity: 0.88; max-width: 560px; margin: 0 auto 28px; }

    .stats-bar {
      background: white;
      border-bottom: 1px solid var(--border);
      padding: 20px 24px;
      display: flex;
      justify-content: center;
      gap: 40px;
      flex-wrap: wrap;
    }
    .stat { text-align: center; }
    .stat .num { font-size: 1.6rem; font-weight: 800; color: var(--green-dark); line-height: 1; }
    .stat .label { font-size: 0.78rem; color: var(--muted); margin-top: 3px; }

    .container { max-width: 860px; margin: 0 auto; padding: 0 24px; }
    .article-body { padding: 48px 0 80px; }

    h2 { font-size: 1.4rem; font-weight: 800; color: var(--green-dark); margin: 40px 0 14px; padding-bottom: 8px; border-bottom: 2px solid var(--green-light); }
    h3 { font-size: 1.05rem; font-weight: 700; color: var(--text); margin: 20px 0 8px; }
    p { margin-bottom: 16px; color: #374151; }

    .breadcrumb { padding: 14px 0; font-size: 0.82rem; color: var(--muted); }
    .breadcrumb a { color: var(--green-mid); text-decoration: none; }

    .info-box {
      background: var(--green-light); border-left: 4px solid var(--green-dark);
      border-radius: 8px; padding: 18px 20px; margin: 24px 0;
    }
    .info-box strong { color: var(--green-dark); }

    /* PROGRAM CARDS */
    .program-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 16px;
      margin: 20px 0 32px;
    }
    .program-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 20px;
      transition: box-shadow 0.2s, transform 0.2s;
      text-decoration: none;
      color: var(--text);
    }
    .program-card:hover { box-shadow: 0 6px 20px rgba(0,0,0,0.09); transform: translateY(-2px); }
    .program-card .icon { font-size: 1.8rem; margin-bottom: 10px; display: block; }
    .program-card h3 { margin: 0 0 6px; font-size: 1rem; color: var(--green-dark); }
    .program-card .count { font-size: 0.82rem; color: var(--muted); font-weight: 600; }
    .program-card .examples { margin-top: 10px; font-size: 0.82rem; color: #6b7280; line-height: 1.5; }

    /* WHY US */
    .why-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 14px;
      margin: 20px 0;
    }
    .why-item {
      background: white;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 18px;
    }
    .why-item .icon { font-size: 1.4rem; margin-bottom: 8px; }
    .why-item h4 { font-size: 0.9rem; font-weight: 700; margin-bottom: 4px; }
    .why-item p { font-size: 0.83rem; margin: 0; color: var(--muted); }

    /* CTA */
    .cta-block {
      background: linear-gradient(135deg, var(--green-dark), var(--green-mid));
      color: white; border-radius: 16px; padding: 36px 28px; text-align: center; margin: 40px 0;
    }
    .cta-block h3 { color: white; font-size: 1.3rem; margin-bottom: 10px; }
    .cta-block p { color: rgba(255,255,255,0.85); margin-bottom: 22px; }
    .btn-wa {
      display: inline-flex; align-items: center; gap: 8px;
      background: #25D366; color: white; padding: 14px 28px;
      border-radius: 8px; text-decoration: none; font-weight: 700; font-size: 1rem;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .btn-wa:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(37,211,102,0.35); }

    /* POPULAR PROGRAMS TABLE */
    table { width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 0.9rem; }
    th { background: var(--green-dark); color: white; padding: 10px 14px; text-align: left; font-weight: 600; }
    td { padding: 10px 14px; border-bottom: 1px solid var(--border); }
    tr:nth-child(even) td { background: #f9fafb; }
    td a { color: var(--green-mid); text-decoration: none; font-weight: 600; }
    td a:hover { text-decoration: underline; }

    footer { background: var(--green-dark); color: rgba(255,255,255,0.75); text-align: center; padding: 28px 24px; font-size: 0.85rem; }
    footer a { color: var(--accent); text-decoration: none; }

    @media (max-width: 600px) { .stats-bar { gap: 20px; } }
